{"version":3,"file":"IncidentList.jsdbx","sources":["../../src/client/components/IncidentList.tsx"],"sourcesContent":["import React from "react";
import {
  NowRecordListConnected,
} from "@servicenow/react-components/NowRecordListConnected";

interface Props {
  onSelect: (id: string) => void;
  onBack: () => void;
}

export default function IncidentList({ onSelect, onBack }: Props) {
  return (
    <div className="campus-app">
      <div className="campus-header">
        <h1 className="section-title">All Incidents</h1>
        <span className="nav-link" onClick={onBack} role="button" tabIndex={0}>
          &larr; Back to Dashboard
        </span>
      </div>
      <NowRecordListConnected
        table="incident"
        listTitle="Incidents"
        columns="number,short_description,priority,state,category,assigned_to,sys_updated_on"
        onRowClicked={(e: any) => onSelect(e.detail.payload.sys_id)}
        onNewActionClicked={() => {
          window.open("/incident.do?sys_id=-1", "_blank");
        }}
      />
    </div>
  );
}
